// A combined bank/merchant introduction uses one quota unit at the same institution for one confirmed case.
Store.prototype.canonicalClient=function(id){const seen=new Set();let c=this.s.clients.find(c=>c.id===id);if(!c)throw Error('Canonical client not found.');while(c.canonicalClientId&&c.canonicalClientId!==c.id){if(seen.has(c.id))throw Error('Canonical client mapping is cyclic.');seen.add(c.id);c=this.s.clients.find(x=>x.id===c.canonicalClientId);if(!c)throw Error('Canonical client mapping is unresolved.');}return c.id;};
